def main() -> None:
    target = Path(__file__).with_name("paragraph_answer_specs.json")
    report_path = Path(__file__).with_name("paragraph_answer_specs_report.json")
    ids = [item["id"] for item in COMMENTS]
    paragraphs = [item["paragraph_index"] for item in COMMENTS]
    if len(ids) != len(set(ids)):
        raise RuntimeError("Duplicate comment id.")
    if len(paragraphs) != len(set(paragraphs)):
        raise RuntimeError("Duplicate paragraph index.")
    for item in COMMENTS:
        text = item["text"]
        if text.count("[[MATH:") != len(MATH_RE.findall(text)):
            raise RuntimeError(f"Unclosed math marker in {item['id']}.")
        if "]]]" in text:
            raise RuntimeError(f"Ambiguous math marker terminator in {item['id']}.")
    target.write_text(json.dumps(COMMENTS, ensure_ascii=False, indent=2), encoding="utf-8")
    report = {
        "comment_count": len(COMMENTS),
        "paragraph_indexes": paragraphs,
        "formula_count": sum(len(MATH_RE.findall(item["text"])) for item in COMMENTS),
        "character_count": sum(len(item["text"]) for item in COMMENTS),
    }
    report_path.write_text(json.dumps(report, ensure_ascii=False, indent=2), encoding="utf-8")
    print(json.dumps(report, ensure_ascii=False, indent=2))


if __name__ == "__main__":
    main()
